//! Shell completion, compatible with what cobra adds to the Go version:
//!
//! - `jv completion {bash|zsh|fish|powershell} [--no-descriptions]` prints
//!   the completion script (the scripts were generated by cobra for jv);
//! - `jv __complete ARGS... PARTIAL` (and `__completeNoDesc`) is the
//!   protocol those scripts call: it prints candidates, one per line
//!   (`name<TAB>description`), followed by `:<directive>`.
//!
//! Command lookup reproduces cobra's `Find`/`stripFlags`, including its
//! quirks, so that the same command lines resolve to the same commands.

use std::ffi::OsString;

use super::flags::{self, FlagKind, FlagSpec, Value};
use super::{Env, Failure, args, help, write_failure};
use crate::gostr;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Shell {
    Bash,
    Fish,
    Powershell,
    Zsh,
}

const SHELLS: [Shell; 4] = [Shell::Bash, Shell::Fish, Shell::Powershell, Shell::Zsh];

impl Shell {
    fn name(self) -> &'static str {
        match self {
            Shell::Bash => "bash",
            Shell::Fish => "fish",
            Shell::Powershell => "powershell",
            Shell::Zsh => "zsh",
        }
    }

    fn script(self) -> &'static str {
        match self {
            Shell::Bash => include_str!("completion/bash.txt"),
            Shell::Fish => include_str!("completion/fish.txt"),
            Shell::Powershell => include_str!("completion/powershell.txt"),
            Shell::Zsh => include_str!("completion/zsh.txt"),
        }
    }

    fn long(self) -> &'static str {
        match self {
            Shell::Bash => help::BASH_LONG,
            Shell::Fish => help::FISH_LONG,
            Shell::Powershell => help::POWERSHELL_LONG,
            Shell::Zsh => help::ZSH_LONG,
        }
    }

    fn usage(self) -> &'static str {
        match self {
            Shell::Bash => help::BASH_USAGE,
            Shell::Fish => help::FISH_USAGE,
            Shell::Powershell => help::POWERSHELL_USAGE,
            Shell::Zsh => help::ZSH_USAGE,
        }
    }
}

/// A command of the (small) cobra command tree.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Cmd {
    Root,
    Completion,
    Shell(Shell),
    /// `__complete`, or its alias `__completeNoDesc`.
    Complete {
        no_desc: bool,
    },
}

const HELP_COMPLETION: FlagSpec = FlagSpec {
    name: "help",
    short: Some(b'h'),
    kind: FlagKind::Bool,
    usage: "help for completion",
};

const SHELL_FLAGS: [[FlagSpec; 2]; 4] = {
    const fn flags(help: &'static str) -> [FlagSpec; 2] {
        [
            FlagSpec {
                name: "help",
                short: Some(b'h'),
                kind: FlagKind::Bool,
                usage: help,
            },
            FlagSpec {
                name: "no-descriptions",
                short: None,
                kind: FlagKind::Bool,
                usage: "disable completion descriptions",
            },
        ]
    }
    [
        flags("help for bash"),
        flags("help for fish"),
        flags("help for powershell"),
        flags("help for zsh"),
    ]
};

impl Cmd {
    fn name(self) -> &'static str {
        match self {
            Cmd::Root => "jv",
            Cmd::Completion => "completion",
            Cmd::Shell(s) => s.name(),
            Cmd::Complete { .. } => "__complete",
        }
    }

    /// Flags once the command runs (cobra adds `--help` at that point),
    /// sorted by name as pflag lists them.
    fn flags(self) -> &'static [FlagSpec] {
        match self {
            Cmd::Root => args::FLAGS,
            Cmd::Completion => std::slice::from_ref(&HELP_COMPLETION),
            Cmd::Shell(s) => {
                &SHELL_FLAGS[SHELLS.iter().position(|&x| x == s).expect("known shell")]
            }
            Cmd::Complete { .. } => &[],
        }
    }

    /// Whether `name` is a flag of this command while commands are being
    /// looked up. `--help` is not registered yet at that point.
    fn lookup_flag(self, long: Option<&str>, short: Option<u8>) -> Option<&'static FlagSpec> {
        self.flags().iter().find(|f| {
            f.name != "help"
                && (long.is_some_and(|l| l == f.name) || short.is_some_and(|s| f.short == Some(s)))
        })
    }
}

/// Which optional commands cobra registers for a given command line.
#[derive(Clone, Copy, Debug, Default)]
struct Tree {
    completion: bool,
    complete: bool,
}

impl Tree {
    /// The tree for `args`, built the way cobra's `ExecuteC` does:
    /// `__complete` exists only when the command line resolves to it, and
    /// `completion` only when the command line resolves to it (directly, or
    /// as the first argument of `__complete`).
    fn for_args(args: &[String]) -> Tree {
        let probe = Tree {
            completion: false,
            complete: true,
        };
        let complete = matches!(find(probe, Cmd::Root, args).0, Cmd::Complete { .. });
        let probe = Tree {
            completion: true,
            complete,
        };
        let completion = match find_shallow(probe, args) {
            (Cmd::Completion, _) => true,
            (Cmd::Complete { .. }, rest) => rest.len() > 1 && rest[0] == "completion",
            _ => false,
        };
        Tree {
            completion,
            complete,
        }
    }

    fn subcommands(self, cmd: Cmd) -> Vec<Cmd> {
        match cmd {
            Cmd::Root => {
                let mut subs = Vec::new();
                if self.complete {
                    subs.push(Cmd::Complete { no_desc: false });
                }
                if self.completion {
                    subs.push(Cmd::Completion);
                }
                subs
            }
            Cmd::Completion => SHELLS.iter().map(|&s| Cmd::Shell(s)).collect(),
            _ => Vec::new(),
        }
    }

    fn find_next(self, cmd: Cmd, name: &str) -> Option<Cmd> {
        self.subcommands(cmd).into_iter().find_map(|c| match c {
            Cmd::Complete { .. } if name == "__complete" => Some(Cmd::Complete { no_desc: false }),
            Cmd::Complete { .. } if name == "__completeNoDesc" => {
                Some(Cmd::Complete { no_desc: true })
            }
            c if c.name() == name && !matches!(c, Cmd::Complete { .. }) => Some(c),
            _ => None,
        })
    }
}

/// cobra's `Find`: descends into subcommands named by the first non-flag
/// argument and returns the command with its remaining arguments.
fn find(tree: Tree, cmd: Cmd, args: &[String]) -> (Cmd, Vec<String>) {
    let words = strip_flags(cmd, args);
    let Some(first) = words.first() else {
        return (cmd, args.to_vec());
    };
    match tree.find_next(cmd, first) {
        Some(sub) => find(tree, sub, &args_minus_first_x(cmd, args, first)),
        None => (cmd, args.to_vec()),
    }
}

/// Like [`find`], but the `completion` command has no shell subcommands yet
/// (cobra adds them only after deciding to keep `completion`).
fn find_shallow(tree: Tree, args: &[String]) -> (Cmd, Vec<String>) {
    let words = strip_flags(Cmd::Root, args);
    let Some(first) = words.first() else {
        return (Cmd::Root, args.to_vec());
    };
    match tree.find_next(Cmd::Root, first) {
        Some(sub) => (sub, args_minus_first_x(Cmd::Root, args, first)),
        None => (Cmd::Root, args.to_vec()),
    }
}

/// `--flag` (without `=`) of a non-bool or unknown flag takes the next
/// argument as its value; so does a two-character `-f`.
fn takes_value(cmd: Cmd, s: &str) -> bool {
    if s.contains('=') {
        return false;
    }
    if let Some(long) = s.strip_prefix("--") {
        return !cmd
            .lookup_flag(Some(long), None)
            .is_some_and(|f| f.kind == FlagKind::Bool);
    }
    s.len() == 2
        && s.starts_with('-')
        && !cmd
            .lookup_flag(None, Some(s.as_bytes()[1]))
            .is_some_and(|f| f.kind == FlagKind::Bool)
}

/// cobra's `stripFlags`: the non-flag words of `args`.
fn strip_flags(cmd: Cmd, args: &[String]) -> Vec<String> {
    let mut words = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let s = &args[i];
        i += 1;
        if s == "--" {
            break;
        }
        if takes_value(cmd, s) {
            // skip the value; cobra stops when it would be the last argument
            if args.len() - i <= 1 {
                break;
            }
            i += 1;
            continue;
        }
        if !s.is_empty() && !s.starts_with('-') {
            words.push(s.clone());
        }
    }
    words
}

/// cobra's `argsMinusFirstX`: `args` without the first non-flag `x`.
fn args_minus_first_x(cmd: Cmd, args: &[String], x: &str) -> Vec<String> {
    let mut pos = 0;
    while pos < args.len() {
        let s = &args[pos];
        if s == "--" {
            break;
        }
        if takes_value(cmd, s) {
            pos += 2;
            continue;
        }
        if !s.starts_with('-') && s == x {
            let mut out = args[..pos].to_vec();
            out.extend_from_slice(&args[pos + 1..]);
            return out;
        }
        pos += 1;
    }
    args.to_vec()
}

/// Resolves the command for a command line. `None` means the root command
/// (the regular `jv` behaviour).
pub(crate) fn resolve(args: &[OsString]) -> Option<(Cmd, Vec<String>)> {
    let strings: Vec<String> = args
        .iter()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let tree = Tree::for_args(&strings);
    if !tree.completion && !tree.complete {
        return None;
    }
    match find(tree, Cmd::Root, &strings) {
        (Cmd::Root, _) => None,
        found => Some(found),
    }
}

/// Runs a completion-related command found by [`resolve`].
pub(crate) fn execute(cmd: Cmd, args: Vec<String>, env: &mut Env<'_>) -> Result<(), Failure> {
    match cmd {
        Cmd::Root => unreachable!("the root command is handled by cli::dispatch"),
        Cmd::Complete { no_desc } => {
            if args.is_empty() {
                return Err(Failure::UsageOf(
                    help::COMPLETE_USAGE,
                    "requires at least 1 arg(s), only received 0".into(),
                ));
            }
            complete(no_desc, &args, env)
        }
        Cmd::Completion | Cmd::Shell(_) => {
            let (long, usage) = match cmd {
                Cmd::Shell(s) => (s.long(), s.usage()),
                _ => (help::COMPLETION_LONG, help::COMPLETION_USAGE),
            };
            let parsed = flags::parse(cmd.flags(), args.into_iter().map(OsString::from).collect())
                .map_err(|e| Failure::UsageOf(usage, e))?;
            let flag = |name: &str| {
                let i = cmd.flags().iter().position(|f| f.name == name)?;
                match parsed.values[i] {
                    Some(Value::Bool(b)) => Some(b),
                    _ => None,
                }
            };
            let Cmd::Shell(shell) = cmd else {
                // `completion` itself only shows its help
                return write!(env.stdout, "{long}\n\n{usage}").map_err(write_failure);
            };
            if flag("help") == Some(true) {
                return write!(env.stdout, "{long}\n\n{usage}").map_err(write_failure);
            }
            if let Some(extra) = parsed.args.first() {
                return Err(Failure::UsageOf(
                    usage,
                    format!(
                        "unknown command {} for {}",
                        gostr::quote(&extra.to_string_lossy()),
                        gostr::quote(&format!("jv completion {}", shell.name()))
                    ),
                ));
            }
            let script = shell.script();
            let script = if flag("no-descriptions") == Some(true) {
                script.replacen("__complete ", "__completeNoDesc ", 1)
            } else {
                script.to_string()
            };
            env.stdout
                .write_all(script.as_bytes())
                .map_err(write_failure)
        }
    }
}

const DIRECTIVE_DEFAULT: u32 = 0;
const DIRECTIVE_NO_FILE_COMP: u32 = 4;

fn directive_name(d: u32) -> &'static str {
    match d {
        DIRECTIVE_NO_FILE_COMP => "ShellCompDirectiveNoFileComp",
        _ => "ShellCompDirectiveDefault",
    }
}

/// The `__complete` protocol.
fn complete(no_desc: bool, args: &[String], env: &mut Env<'_>) -> Result<(), Failure> {
    let (completions, directive, error) = get_completions(args);
    if let Some(e) = error {
        let _ = writeln!(env.stderr, "[Debug] [Error] {e}");
    }
    // `JV_COMPLETION_DESCRIPTIONS` (or `COBRA_COMPLETION_DESCRIPTIONS`)
    // turns descriptions off when set to a false value.
    let no_desc = no_desc
        || env
            .completion_descriptions
            .as_deref()
            .and_then(flags::parse_go_bool)
            .is_some_and(|b| !b);
    let mut out = String::new();
    for comp in completions {
        let comp = if no_desc {
            comp.split('\t').next().unwrap_or_default()
        } else {
            &comp
        };
        let comp = comp.split('\n').next().unwrap_or_default();
        out.push_str(comp.trim());
        out.push('\n');
    }
    out.push_str(&format!(":{directive}\n"));
    env.stdout
        .write_all(out.as_bytes())
        .map_err(write_failure)?;
    env.stdout.flush().map_err(write_failure)?;
    let _ = writeln!(
        env.stderr,
        "Completion ended with directive: {}",
        directive_name(directive)
    );
    Ok(())
}

/// cobra's `getCompletions` for jv's commands: completes flag names, and
/// otherwise falls back to the shell's file completion.
fn get_completions(args: &[String]) -> (Vec<String>, u32, Option<String>) {
    let (to_complete, trimmed) = args.split_last().expect("at least one argument");
    // `completion` is registered when it is the first argument of
    // `__complete`; `__complete` itself is dropped while completing.
    let tree = Tree {
        completion: args.len() > 1 && args[0] == "completion",
        complete: false,
    };
    let (cmd, final_args) = find(tree, Cmd::Root, trimmed);
    let specs = cmd.flags();

    let (flag, final_args, to_complete, flag_err) =
        check_if_flag_completion(cmd, final_args, to_complete);

    let mut with_dash = final_args.clone();
    with_dash.push("--".into());
    let new_count = flags::parse(specs, to_os(&with_dash))
        .map(|p| p.args.len())
        .unwrap_or(0);
    let parsed = match flags::parse(specs, to_os(&final_args)) {
        Ok(p) => p,
        Err(e) => {
            let msg = format!(
                "Error while parsing flags from args [{}]: {e}",
                final_args.join(" ")
            );
            return (Vec::new(), DIRECTIVE_DEFAULT, Some(msg));
        }
    };
    let flag_completion = new_count <= parsed.args.len();
    if let Some(e) = flag_err
        && flag_completion
    {
        return (Vec::new(), DIRECTIVE_DEFAULT, Some(e));
    }
    let help = specs.iter().position(|f| f.name == "help");
    // `--help` given at all (even `--help=false`) ends completion
    if help.is_some_and(|i| parsed.changed(i)) {
        return (Vec::new(), DIRECTIVE_NO_FILE_COMP, None);
    }
    let positional = &parsed.args;

    if flag.is_none()
        && to_complete.starts_with('-')
        && !to_complete.contains('=')
        && flag_completion
    {
        let mut completions = Vec::new();
        for (i, f) in specs.iter().enumerate() {
            if parsed.changed(i) {
                continue;
            }
            let long = format!("--{}", f.name);
            if long.starts_with(&to_complete) {
                completions.push(format!("{long}\t{}", f.usage));
            }
            if let Some(c) = f.short {
                let short = format!("-{}", char::from(c));
                if short.starts_with(&to_complete) {
                    completions.push(format!("{short}\t{}", f.usage));
                }
            }
        }
        return (completions, DIRECTIVE_NO_FILE_COMP, None);
    }

    let mut completions = Vec::new();
    let mut directive = DIRECTIVE_DEFAULT;
    if flag.is_none() {
        let any_flag_set = (0..specs.len()).any(|i| parsed.changed(i));
        if positional.is_empty() && !any_flag_set {
            let subs = match cmd {
                Cmd::Completion => SHELLS.iter().map(|&s| Cmd::Shell(s)).collect(),
                // `__complete` is hidden; `completion` is listed when present
                Cmd::Root if tree.completion => vec![Cmd::Completion],
                _ => Vec::new(),
            };
            for sub in subs {
                if sub.name().starts_with(to_complete.as_str()) {
                    completions.push(format!("{}\t{}", sub.name(), short_description(sub)));
                }
                directive = DIRECTIVE_NO_FILE_COMP;
            }
        }
    }
    // `completion` and the shell commands never complete file names.
    let completing_flag_value = flag.is_some() && flag_completion;
    if !completing_flag_value && matches!(cmd, Cmd::Completion | Cmd::Shell(_)) {
        directive = DIRECTIVE_NO_FILE_COMP;
    }
    (completions, directive, None)
}

fn short_description(cmd: Cmd) -> String {
    match cmd {
        Cmd::Completion => "Generate the autocompletion script for the specified shell".into(),
        Cmd::Shell(s) => format!("Generate the autocompletion script for {}", s.name()),
        _ => String::new(),
    }
}

fn to_os(args: &[String]) -> Vec<OsString> {
    args.iter().map(OsString::from).collect()
}

/// cobra's `checkIfFlagCompletion`: whether the word being completed is the
/// value of a flag (`--path <TAB>`, `--color=<TAB>`). Returns the flag, the
/// arguments without that flag name, the partial value and an error for
/// unknown flags.
fn check_if_flag_completion(
    cmd: Cmd,
    args: Vec<String>,
    last: &str,
) -> (
    Option<&'static FlagSpec>,
    Vec<String>,
    String,
    Option<String>,
) {
    let lb = last.as_bytes();
    let mut flag_name: Option<Vec<u8>> = None;
    let mut trimmed = args.clone();
    let mut to_complete = last.to_string();
    let mut with_equal = false;
    if lb.first() == Some(&b'-') {
        let Some(idx) = last.find('=') else {
            return (None, args, last.to_string(), None);
        };
        flag_name = Some(if lb.starts_with(b"--") {
            lb[2..idx].to_vec()
        } else {
            lb[idx - 1..idx].to_vec()
        });
        to_complete = last[idx + 1..].to_string();
        with_equal = true;
        if flag_name.as_ref().is_some_and(|n| n.is_empty()) {
            flag_name = None;
        }
    }
    if flag_name.is_none()
        && let Some(prev) = args.last()
    {
        let pb = prev.as_bytes();
        let is_flag_arg = (pb.len() >= 3 && pb.starts_with(b"--"))
            || (pb.len() >= 2 && pb[0] == b'-' && pb[1] != b'-');
        if is_flag_arg && !prev.contains('=') {
            flag_name = Some(if pb.starts_with(b"--") {
                pb[2..].to_vec()
            } else {
                pb[pb.len() - 1..].to_vec()
            });
            trimmed = args[..args.len() - 1].to_vec();
        }
    }
    let Some(name) = flag_name else {
        return (None, trimmed, to_complete, None);
    };
    let specs = cmd.flags();
    let found = if name.len() == 1 {
        specs.iter().find(|f| f.short == Some(name[0]))
    } else {
        specs.iter().find(|f| f.name.as_bytes() == name.as_slice())
    };
    let Some(spec) = found else {
        let msg = format!(
            "Subcommand '{}' does not support flag '{}'",
            cmd.name(),
            String::from_utf8_lossy(&name)
        );
        return (None, args, last.to_string(), Some(msg));
    };
    if !with_equal && spec.kind == FlagKind::Bool {
        // `--raw <TAB>`: the word is not the flag's value
        return (None, args, to_complete, None);
    }
    (Some(spec), trimmed, to_complete, None)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(v: &[&str]) -> Vec<String> {
        v.iter().map(|x| x.to_string()).collect()
    }

    #[test]
    fn strip_flags_like_cobra() {
        assert_eq!(
            strip_flags(Cmd::Root, &s(&["-c", "never", "completion", "bash"])),
            s(&["completion", "bash"])
        );
        assert_eq!(
            strip_flags(Cmd::Root, &s(&["-r", "completion"])),
            s(&["completion"])
        );
        // `-h` is not registered during lookup, so it is assumed to take a value
        assert_eq!(
            strip_flags(Cmd::Root, &s(&["-h", "completion", "bash"])),
            s(&["bash"])
        );
        // a value flag that would consume the last argument stops the scan
        assert_eq!(
            strip_flags(Cmd::Root, &s(&["-p", "completion"])),
            Vec::<String>::new()
        );
        assert_eq!(
            strip_flags(Cmd::Root, &s(&["--", "completion"])),
            Vec::<String>::new()
        );
    }

    #[test]
    fn resolves_commands() {
        let os = |v: &[&str]| v.iter().map(OsString::from).collect::<Vec<_>>();
        assert_eq!(resolve(&os(&["file.json"])), None);
        assert_eq!(
            resolve(&os(&["completion", "bash"])),
            Some((Cmd::Shell(Shell::Bash), vec![]))
        );
        assert_eq!(
            resolve(&os(&["completion"])),
            Some((Cmd::Completion, vec![]))
        );
        assert_eq!(
            resolve(&os(&["__completeNoDesc", "-"])).map(|r| r.0),
            Some(Cmd::Complete { no_desc: true })
        );
        assert_eq!(resolve(&os(&["x", "completion"])), None);
    }

    #[test]
    fn flag_name_completion() {
        let (c, d, e) = get_completions(&s(&["-r", "--r"]));
        assert_eq!((c, d, e), (vec![], DIRECTIVE_NO_FILE_COMP, None));
        let (c, _, _) = get_completions(&s(&["--c"]));
        assert_eq!(c.len(), 2);
        assert!(c[0].starts_with("--color\t"));
        let (c, d, _) = get_completions(&s(&["--color", ""]));
        assert_eq!((c.len(), d), (0, DIRECTIVE_DEFAULT));
        let (_, _, e) = get_completions(&s(&["--bogus=x"]));
        assert_eq!(
            e.as_deref(),
            Some("Subcommand 'jv' does not support flag 'bogus'")
        );
    }
}
